/* waits for Enter; the line keeps its newline when the input has one; "" at end of input */
static df_string df_console_get_input(void) {
  fflush(stdout);
  uint64_t capacity = 128;
  uint64_t length = 0;
  char* buffer = (char*)df_alloc(capacity);
  int next;
  while ((next = getc(stdin)) != EOF) {
    if (length == capacity) {
      char* bigger = (char*)df_alloc(capacity * 2);
      memcpy(bigger, buffer, length);
      buffer = bigger;
      capacity *= 2;
    }
    buffer[length++] = (char)next;
    if (next == '\n') {
      break;
    }
  }
  df_string s = { buffer, length };
  return s;
}

/* one UTF-8 character from a byte reader; 0 at end of input */
static uint32_t df_decode_utf8(int first, int (*read_byte)(void)) {
  if (first < 0x80) {
    return (uint32_t)first;
  }
  int extra = (first & 0xE0) == 0xC0 ? 1 : (first & 0xF0) == 0xE0 ? 2 : (first & 0xF8) == 0xF0 ? 3 : 0;
  uint32_t code = (uint32_t)(first & (0x3F >> extra));
  for (int index = 0; index < extra; index++) {
    int next = read_byte();
    if (next == EOF) {
      return 0;
    }
    code = (code << 6) | (uint32_t)(next & 0x3F);
  }
  return code;
}

static int df_read_stdin_byte(void) {
  return getc(stdin);
}

#ifdef _WIN32
#include <conio.h>
#include <io.h>
#else
#include <termios.h>
#include <unistd.h>
#endif

/* the first typable character, without waiting for Enter; '\0' at end of input */
static uint32_t df_console_get_char(void) {
  fflush(stdout);
#ifdef _WIN32
  if (_isatty(_fileno(stdin))) {
    while (true) {
      wint_t key = _getwch();
      if (key == 0 || key == 0xE0) {
        _getwch();              /* arrows and function keys: two codes */
        continue;
      }
      if (key >= 0xD800 && key <= 0xDBFF) {
        wint_t low = _getwch();
        return 0x10000 + (((uint32_t)key - 0xD800) << 10) + ((uint32_t)low - 0xDC00);
      }
      if (key >= 0x20 && key != 0x7F) {
        return (uint32_t)key;
      }
    }
  }
#else
  if (isatty(STDIN_FILENO)) {
    struct termios saved;
    tcgetattr(STDIN_FILENO, &saved);
    struct termios raw = saved;
    raw.c_lflag &= (tcflag_t)~(ICANON | ECHO);
    raw.c_cc[VMIN] = 1;
    raw.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSANOW, &raw);
    uint32_t result = 0;
    while (true) {
      int first = getc(stdin);
      if (first == EOF) {
        break;
      }
      if (first == 0x1B) {
        /* escape sequence (arrows, function keys): skip it */
        int second = getc(stdin);
        if (second == '[' || second == 'O') {
          int part;
          while ((part = getc(stdin)) != EOF && !(part >= 0x40 && part <= 0x7E)) {
          }
        }
        continue;
      }
      if (first < 0x20 || first == 0x7F) {
        continue;
      }
      result = df_decode_utf8(first, df_read_stdin_byte);
      break;
    }
    tcsetattr(STDIN_FILENO, TCSANOW, &saved);
    return result;
  }
#endif
  /* not a terminal: the next typable character of the input */
  while (true) {
    int first = getc(stdin);
    if (first == EOF) {
      return 0;
    }
    if (first >= 0x20 && first != 0x7F) {
      return df_decode_utf8(first, df_read_stdin_byte);
    }
  }
}

static void df_init(void) {
#ifdef _WIN32
  SetConsoleOutputCP(CP_UTF8);
  SetConsoleCP(CP_UTF8);
#endif
  atexit(df_exc_report);
}

/* ---- program arguments (spec 17.1): index 0 is the program name ---- */

#ifdef _WIN32
#include <shellapi.h>
#pragma comment(lib, "shell32.lib")
#endif

static df_arr_string df_args;

static void df_set_args(int argc, char** argv) {
#ifdef _WIN32
  /* the C arguments use the ANSI code page: read the wide command line and convert it to UTF-8 */
  int count = 0;
  wchar_t** wide = CommandLineToArgvW(GetCommandLineW(), &count);
  if (wide) {
    df_args.p = (df_string*)df_calloc((uint64_t)count, sizeof(df_string));
    df_args.len = (uint64_t)count;
    for (int index = 0; index < count; index++) {
      int bytes = WideCharToMultiByte(CP_UTF8, 0, wide[index], -1, NULL, 0, NULL, NULL);
      char* text = (char*)df_alloc((uint64_t)bytes);
      WideCharToMultiByte(CP_UTF8, 0, wide[index], -1, text, bytes, NULL, NULL);
      df_args.p[index].p = text;
      df_args.p[index].len = (uint64_t)(bytes > 0 ? bytes - 1 : 0);
    }
    LocalFree(wide);
    return;
  }
#endif
  df_args.p = (df_string*)df_calloc((uint64_t)argc, sizeof(df_string));
  df_args.len = (uint64_t)argc;
  for (int index = 0; index < argc; index++) {
    df_args.p[index].p = argv[index];
    df_args.p[index].len = strlen(argv[index]);
  }
}

static df_arr_string df_get_args(void) {
  return df_args;
}

/* ---- checked integer division ---- */

/* on division by zero: raise DivisionByZeroException and return 0; the caller checks df_err */
#define DF_DIV_SIGNED(T, NAME, MIN) \
  static T df_div_##NAME(T a, T b, const char* function) { \
    if (b == 0) { df_raise(&df_desc_DivisionByZeroException, function); return 0; } \
    if (b == -1) return (T)(0 - (uint64_t)a); \
    return (T)(a / b); \
  } \
  static T df_mod_##NAME(T a, T b, const char* function) { \
    if (b == 0) { df_raise(&df_desc_DivisionByZeroException, function); return 0; } \
    if (b == -1) return 0; \
    return (T)(a % b); \
  }

#define DF_DIV_UNSIGNED(T, NAME) \
  static T df_div_##NAME(T a, T b, const char* function) { \
    if (b == 0) { df_raise(&df_desc_DivisionByZeroException, function); return 0; } \
    return (T)(a / b); \
  } \
  static T df_mod_##NAME(T a, T b, const char* function) { \
    if (b == 0) { df_raise(&df_desc_DivisionByZeroException, function); return 0; } \
    return (T)(a % b); \
  }

